//! Optional AOT source generation; no compiler or dynamic loading in the engine.
use crate::{CompiledNetwork, contracts::Model, diagnostic::Diagnostic, network::Term};
use std::fmt::Write;

/// Emit one Rust module defining `GeneratedKernel`. Named coefficients are read
/// from each bound network, so parameter optimization needs no recompilation.
/// Custom laws are rejected; higher mass-action orders use the checked fallback.
pub fn mass_action_source(model_bytes: &[u8]) -> Result<String, Vec<Diagnostic>> {
    let model: Model = crate::parse_model(model_bytes).map_err(|e| vec![e])?;
    let network = CompiledNetwork::compile(&model)?;
    if model
        .reactions
        .iter()
        .any(|r| !matches!(r.rate, crate::contracts::Rate::MassAction { .. }))
    {
        return Err(vec![Diagnostic::error(
            "CRN-E020",
            "/kernel",
            "source generation requires mass-action laws",
            "Use the reusable dynamic evaluator for custom laws.",
        )]);
    }
    let mut out = format!(
        "// Generated by CRN-craft; preserve the checked fallback.\n\
        pub struct GeneratedKernel;\n\
        impl crn_craft::ssa::PropensityKernel for GeneratedKernel {{\n\
        fn topology_sha256(&self) -> &str {{ {:?} }}\n\
        #[inline] fn evaluate(&self, net: &crn_craft::CompiledNetwork, rx: usize, state: &[i64]) -> Result<f64, crn_craft::diagnostic::Diagnostic> {{\n\
        match rx {{\n",
        network.topology_sha256()
    );
    for (rx, r) in network.reactions().iter().enumerate() {
        let expression = match r.reactants.as_slice() {
            [] => "let value = c;".to_owned(),
            [a] if a.coefficient == 1 => format!("let value = c * state[{}] as f64;", a.species),
            [a] if a.coefficient == 2 => format!(
                "let n = state[{}]; let first = if n == 2 {{ c }} else if n == 3 {{ c * 3.0 }} else {{ c * (n - 1) as f64 }}; if !first.is_normal() {{ return net.propensity_in_scheduler_state(rx, state); }} let value = if n <= 3 {{ first }} else {{ first * (n as f64 / 2.0) }};",
                a.species
            ),
            [a, b] if a.coefficient == 1 && b.coefficient == 1 => format!(
                "let first = c * state[{}] as f64; if !first.is_normal() {{ return net.propensity_in_scheduler_state(rx, state); }} let value = first * state[{}] as f64;",
                a.species, b.species
            ),
            _ => continue,
        };
        writeln!(out, "{rx} => {{").unwrap();
        for Term {
            species,
            coefficient,
        } in &r.reactants
        {
            writeln!(
                out,
                "if state[{species}] < {coefficient} {{ return Ok(0.0); }}"
            )
            .unwrap();
        }
        writeln!(out, "if let Some(c) = net.mass_action_coefficient({rx}) {{\nif c == 0.0 {{ return Ok(0.0); }}\nif c.is_normal() {{ {expression} if value.is_normal() {{ return Ok(value); }} }}\n}}\nnet.propensity_in_scheduler_state(rx, state)\n}},").unwrap();
    }
    out.push_str("_ => net.propensity_in_scheduler_state(rx, state),\n}\n}\n}\n");
    Ok(out)
}
